<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ÉLAN / Studio access</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600&display=swap" rel="stylesheet"><style>body{margin:0;background:#0d0e0e;color:#f4f1e9;font-family:DM Sans,Arial,sans-serif;display:grid;min-height:100vh;place-items:center}.wrap{width:min(460px,calc(100vw - 40px));border:1px solid rgba(255,255,255,.15);padding:48px;background:#111313}.brand{letter-spacing:.18em;font-weight:700}.brand small{display:block;margin-top:8px;opacity:.5;font-size:9px;letter-spacing:.14em;text-transform:uppercase}.ey{margin-top:70px;color:#999;letter-spacing:.18em;font-size:9px;text-transform:uppercase}.serif{font-family:'Playfair Display',serif;font-size:60px;line-height:.92;margin:16px 0 42px;letter-spacing:-.05em}.field{margin:14px 0}.field label{display:block;font-size:9px;text-transform:uppercase;letter-spacing:.14em;color:#888;margin-bottom:7px}.field input{width:100%;box-sizing:border-box;padding:15px 0;background:transparent;color:#fff;border:0;border-bottom:1px solid #333;outline:0}.btn{width:100%;margin-top:25px;padding:16px;border:0;background:#f3f0e9;color:#101110;text-transform:uppercase;letter-spacing:.1em;font-size:10px;font-weight:600}.err{color:#ff9e92;font-size:11px;margin-bottom:14px}@media(max-width:600px){.wrap{padding:32px}.serif{font-size:48px}}</style></head><body><main class="wrap"><div class="brand">ÉLAN<small>Travel Studio / private access</small></div><div class="ey">Studio console</div><h1 class="serif">Welcome<br><em>back.</em></h1><?php if($errors->any()): ?><div class="err"><?php echo e($errors->first()); ?></div><?php endif; ?><form method="post" action="<?php echo e(route('admin.login')); ?>"><?php echo csrf_field(); ?><div class="field"><label>Email</label><input type="email" name="email" value="<?php echo e(old('email')); ?>" autocomplete="username" required></div><div class="field"><label>Password</label><input type="password" name="password" autocomplete="current-password" required></div><button class="btn">Enter studio ↗</button></form></main></body></html><?php /**PATH C:\xampp\htdocs\elan-travel\resources\views/auth/login.blade.php ENDPATH**/ ?>